import React from 'react'
import { FaStar, FaRegStar } from 'react-icons/fa'

const Stars = ({ stars, rating }) => {
    const ratingStars = Array.from({ length: 5 }, (elem, index) => {
        return (
            <span key={index} >
                {
                    stars >= index + 1 ? (
                        <FaStar className="inline-block w-[19.37px] h-[19.37px] text-[#004B95] pr-[4.04px] text-[12px]" />
                    ) : (
                        <FaRegStar className="inline-block w-[19.37px] h-[19.37px] text-[#004B95] pr-[4.04px] text-[12px]" />
                    )
                }
            </span>
        )
    })
    return (
        <div className='flex items-baseline '>
            <div className=''>{ratingStars}</div>
            <p className='text-[12px] text-[#004B95]'>( {rating} )</p>
        </div>
    )
}

export default Stars