import React from "react";
import LikeShare from "./LikeShare";
import Stars from "./Stars";
import { getResponsiveSrcSet } from "../../utils/imageHelpers";
import { Link } from "@tanstack/react-router";

const ProductCard = React.memo(({
  title,
  link,
  description,
  img,
  rating,
  stars,
  setProductShown,
  index,
  liked,
}) => {
  // Pure CSS entrance animation — avoids JS scroll calculations of AOS
  const animStyle = {
    animation: "cardFadeIn 0.5s ease both",
    animationDelay: `${(index % 8) * 50}ms`,
  };

  return (
    <div
      style={animStyle}
      className="w-auto pb-[26px] px-4 h-[230px] rounded-[10px] border-[2px] hover:border-[#004B95] bg-white shadow-[0px_4px_20px_rgba(166,166,166,0.3)]"
    >
      <div className="flex justify-between items-center ">
        <Link
          to={"/product/" + link}
          className={`text-start font-poppins font-bold text-[16px] leading-[131%] tracking-[0.055em] text-[#004B95]`}
        >
          {title}
        </Link>
        <LikeShare
          liked={liked}
          title={title}
          isCategory={false}
          link={"/product/" + link}
          image={img}
        />
      </div>
      <Link to={"/product/" + link}>
        <img
          className="w-[80%] mx-[10%] h-[30%] object-contain relative"
          src={img}
          srcSet={getResponsiveSrcSet(img)}
          sizes="(max-width: 640px) 95vw, (max-width: 1024px) 45vw, (max-width: 1600px) 22vw, 400px"
          alt={title}
          width="640"
          height="480"
          loading="lazy"
        />

      </Link>
      {/* rating */}
      <Stars rating={rating} stars={stars} />

      <div className="text-center ">
        <Link
          to={"/product/" + link}
          aria-label={`Read more about ${title}`}
          className="text-center text-[#FFFFFF] bg-[#004B95] w-full h-[40px] rounded-[5px] font-poppins font-medium text-[18px] leading-[25.83px] tracking-[6%] flex justify-center items-center"
          onClick={() => {
            if (typeof setProductShown === "function") {
              setProductShown(index);
            }
          }}
        >
          Read More <span className="sr-only">about {title}</span>
        </Link>
      </div>
    </div>
  );
});

export default ProductCard;
